// Generated by AI (UnitTest MCP)
//! Merge verification against a real repository.
//!
//! These build an actual git repository rather than mocking git, because the
//! whole value of ADR-0058 is that git answers the question and we do not. A
//! mock would assert that our own beliefs about `merge-base --is-ancestor` are
//! self-consistent, which is not the property under test.

use std::path::{Path, PathBuf};
use std::process::Command;

use crate::merge::verify_merge;

/// Run git in the fixture, with the parent's git environment cleared.
///
/// Not optional. A child git that inherits `GIT_DIR`, `GIT_INDEX_FILE` or the
/// object-directory variables operates on the *parent* repository, so a fixture
/// commit lands in the real checkout. That happened in this repository once
/// already (PR #21) and cost a restore.
fn git(root: &Path, args: &[&str]) -> String {
    let output = Command::new("git")
        .args(args)
        .current_dir(root)
        .env_remove("GIT_DIR")
        .env_remove("GIT_WORK_TREE")
        .env_remove("GIT_COMMON_DIR")
        .env_remove("GIT_INDEX_FILE")
        .env_remove("GIT_OBJECT_DIRECTORY")
        .env_remove("GIT_ALTERNATE_OBJECT_DIRECTORIES")
        .output()
        .expect("git runs");
    assert!(
        output.status.success(),
        "git {:?} failed: {}",
        args,
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).trim().to_string()
}

fn write(root: &Path, relative: &str, contents: &str) {
    let path = root.join(relative);
    std::fs::create_dir_all(path.parent().expect("has a parent")).expect("mkdir");
    std::fs::write(path, contents).expect("write");
}

/// A repository with `main`, plus a side branch merged into it.
///
/// Returns the fixture root, the branch commit that landed, the two-parent
/// merge commit that landed it, and a commit that was never merged.
///
/// `merged` and `merge_commit` are deliberately both kept. They are different
/// shapes and git treats them differently: a diff of a two-parent commit is
/// empty unless asked for with `-m`, so a test that only ever passes the
/// single-parent one cannot see that. This fixture used to return only
/// `merged` while its doc called it "the merge commit on `main`", and the tool
/// asks callers for exactly the shape that was missing.
struct Fixture {
    root: PathBuf,
    merged: String,
    merge_commit: String,
    unmerged: String,
}

fn fixture(name: &str) -> Fixture {
    let root = std::env::temp_dir().join(format!("lodestar-merge-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).expect("mkdir");

    git(&root, &["init", "--initial-branch=main"]);
    git(&root, &["config", "user.email", "fixture@example.invalid"]);
    git(&root, &["config", "user.name", "fixture"]);
    git(&root, &["config", "commit.gpgsign", "false"]);

    write(&root, "README.md", "base\n");
    git(&root, &["add", "README.md"]);
    git(&root, &["commit", "-m", "base"]);

    // Work on a side branch, merged into main: this is the shape ADR-0058 cares
    // about, a commit that landed.
    git(&root, &["checkout", "-b", "feature"]);
    write(&root, "crates/thing/src/lib.rs", "pub fn thing() {}\n");
    git(&root, &["add", "crates/thing/src/lib.rs"]);
    git(&root, &["commit", "-m", "feat: the thing"]);
    let merged = git(&root, &["rev-parse", "HEAD"]);
    git(&root, &["checkout", "main"]);
    git(&root, &["merge", "--no-ff", "--no-edit", "feature"]);
    // The two-parent commit itself: what an agent actually names, and what a
    // plain `git show --name-only` reports nothing for.
    let merge_commit = git(&root, &["rev-parse", "HEAD"]);

    // Work that never landed, on a branch main cannot reach.
    git(&root, &["checkout", "-b", "abandoned"]);
    write(&root, "crates/thing/src/other.rs", "pub fn other() {}\n");
    git(&root, &["add", "crates/thing/src/other.rs"]);
    git(&root, &["commit", "-m", "feat: never merged"]);
    let unmerged = git(&root, &["rev-parse", "HEAD"]);
    git(&root, &["checkout", "main"]);

    Fixture {
        root,
        merged,
        merge_commit,
        unmerged,
    }
}

#[test]
fn a_merged_commit_inside_the_declared_scope_verifies() {
    let f = fixture("accepts");
    let scope = vec!["crates/thing/**".to_string()];

    let proof = verify_merge(&f.root, &f.merged, "main", &scope).expect("verifies");

    assert_eq!(proof.commit, f.merged, "the resolved hash is returned");
    assert!(
        proof
            .changed_paths
            .contains(&"crates/thing/src/lib.rs".to_string()),
        "the touched paths are reported: {:?}",
        proof.changed_paths
    );
}

/// Regression: the two-parent merge commit is the shape the tool asks for, and
/// the one shape nothing tested.
///
/// `git show --pretty=format: --name-only <merge>` prints nothing at all — git
/// suppresses diff output for a commit with two parents unless asked with `-m`,
/// `-c` or `--first-parent`. So the verb whose entire premise is "a merge is
/// evidence" saw an empty file list for precisely the commits it exists to
/// read, and refused them as touching nothing inside the task's scope.
///
/// The old fixture hid this by capturing the *feature* commit and calling it
/// `merged`: a single-parent commit reachable from `main`, which diffs fine.
#[test]
fn the_two_parent_merge_commit_reports_the_paths_it_carried() {
    let f = fixture("mergecommit");
    let scope = vec!["crates/thing/**".to_string()];

    // It really is a merge: two parents, which is what breaks a plain diff.
    let parents = git(
        &f.root,
        &["rev-list", "--parents", "-n", "1", &f.merge_commit],
    );
    assert_eq!(
        parents.split_whitespace().count(),
        3,
        "fixture must produce a two-parent merge, got: {parents}"
    );

    let proof = verify_merge(&f.root, &f.merge_commit, "main", &scope).expect("verifies");

    assert_eq!(proof.commit, f.merge_commit);
    assert!(
        proof
            .changed_paths
            .contains(&"crates/thing/src/lib.rs".to_string()),
        "a merge must report the paths it carried, not an empty list: {:?}",
        proof.changed_paths
    );
}

/// Regression: the integration ref must be `origin/main`, not the local `main`.
///
/// Under ADR-0038 every workstream gets its own linked worktree and nobody
/// checks `main` out, so the local branch sits wherever the clone left it —
/// measured 294 commits behind on this repository, which refused a merge that
/// was demonstrably on the integration branch. The refusal blamed the commit,
/// not the ref it was compared against, which is what made it expensive to see.
#[test]
fn the_integration_ref_prefers_the_remote_tracking_branch() {
    let f = fixture("integref");

    // No remote yet: the single-checkout case the original name assumed.
    assert_eq!(
        crate::merge::integration_ref(&f.root),
        "main",
        "without a remote-tracking ref there is nothing else to use"
    );

    // Give it an `origin/main` that is deliberately *behind* local `main`, the
    // shape a linked worktree actually has, and it must still be preferred.
    git(
        &f.root,
        &["update-ref", "refs/remotes/origin/main", &f.merge_commit],
    );
    assert_eq!(
        crate::merge::integration_ref(&f.root),
        "origin/main",
        "the protected branch's remote-tracking ref is the published truth"
    );
}

// An abbreviation must resolve to the same commit, because git resolves it
// rather than us pattern-matching the string.
#[test]
fn an_abbreviated_hash_resolves_to_the_full_commit() {
    let f = fixture("abbrev");
    let scope = vec!["crates/thing/**".to_string()];

    let proof = verify_merge(&f.root, &f.merged[..8], "main", &scope).expect("verifies");

    assert_eq!(proof.commit, f.merged);
}

// The load-bearing refusal: work that has not landed is not evidence that it
// shipped. Without this the whole verb is a rubber stamp.
#[test]
fn a_commit_that_never_merged_is_refused() {
    let f = fixture("unmerged");
    let scope = vec!["crates/thing/**".to_string()];

    let error = verify_merge(&f.root, &f.unmerged, "main", &scope)
        .expect_err("an unmerged commit must be refused");

    let message = error.to_string();
    assert!(
        message.contains("not reachable"),
        "the refusal must say why: {message}"
    );
}

// A commit that touched none of the task's paths is somebody else's work, and
// accepting it is exactly the laundering ADR-0058 warns about.
#[test]
fn a_commit_outside_the_declared_scope_is_refused() {
    let f = fixture("outside");
    let scope = vec!["editors/vscode/**".to_string()];

    let error = verify_merge(&f.root, &f.merged, "main", &scope)
        .expect_err("a commit outside scope must be refused");

    assert!(error.to_string().contains("declared scope"), "{error}");
}

// A task that declared nothing would otherwise accept any merged commit in the
// repository as its own receipt, so the caller is told rather than waved past.
#[test]
fn a_task_with_no_declared_scope_is_told_rather_than_waved_through() {
    let f = fixture("noscope");

    let error =
        verify_merge(&f.root, &f.merged, "main", &[]).expect_err("an empty scope must be refused");

    assert!(error.to_string().contains("no path scope"), "{error}");
}

// A hash that does not resolve is refused with the command that produces a real
// one, because the caller is the only one who can supply a correct value.
#[test]
fn a_hash_git_cannot_resolve_is_refused() {
    let f = fixture("bogus");
    let scope = vec!["crates/thing/**".to_string()];

    let error = verify_merge(
        &f.root,
        "0123456789abcdef0123456789abcdef01234567",
        "main",
        &scope,
    )
    .expect_err("an unresolvable hash must be refused");

    assert!(error.to_string().contains("rev-parse"), "{error}");
}

// The point of ADR-0058, end to end: the agent names a commit and the plane
// derives the bundle, rather than the agent describing work it already finished.
#[test]
fn merge_evidence_derives_the_bundle_from_what_git_reports() {
    let f = fixture("facade");
    let engine = crate::Lodestar::open_in_memory()
        .unwrap()
        .with_workspace_root(f.root.to_string_lossy());
    let goal = engine
        .define_goal(crate::GoalKind::Objective, "Ship", "ship the thing", None)
        .unwrap();
    let task = engine.create_task(&goal.id, "build it", "built").unwrap();
    let scope = crate::TaskScope {
        paths: vec!["crates/thing/**".to_string()],
        symbols: Vec::new(),
    };
    assert!(engine
        .claim_task_with_scope(&task.id, "agent-a", 300, &scope)
        .unwrap());

    let evidence = engine
        .merge_evidence(&task.id, &f.merged, "agent-a")
        .expect("a landed merge inside scope is evidence");

    assert_eq!(evidence.commit_ids, vec![format!("intent:{}", f.merged)]);
    assert!(
        evidence
            .changed_node_ids
            .contains(&"artifact:crates/thing/src/lib.rs".to_string()),
        "nodes come from git, not from the caller: {:?}",
        evidence.changed_node_ids
    );
    assert_eq!(evidence.task_id.as_deref(), Some(task.id.as_str()));
    assert!(
        evidence
            .provenance
            .iter()
            .any(|p| p.relation == "refactored"),
        "a verified merge is a provenance-bearing mutation"
    );
}

// A merge proves who shipped the work, not who may claim credit for it.
#[test]
fn merge_evidence_refuses_a_task_this_agent_does_not_hold() {
    let f = fixture("notmine");
    let engine = crate::Lodestar::open_in_memory()
        .unwrap()
        .with_workspace_root(f.root.to_string_lossy());
    let goal = engine
        .define_goal(crate::GoalKind::Objective, "Ship", "ship the thing", None)
        .unwrap();
    let task = engine.create_task(&goal.id, "build it", "built").unwrap();
    let scope = crate::TaskScope {
        paths: vec!["crates/thing/**".to_string()],
        symbols: Vec::new(),
    };
    assert!(engine
        .claim_task_with_scope(&task.id, "agent-a", 300, &scope)
        .unwrap());

    let error = engine
        .merge_evidence(&task.id, &f.merged, "agent-b")
        .expect_err("a merge is not a way to collect somebody else's receipt");

    assert!(error.to_string().contains("not held by"), "{error}");
}

// Without a declared checkout the plane would be verifying against whatever
// directory the server started in, which proves nothing about this repository.
#[test]
fn merge_evidence_says_so_when_it_does_not_know_the_checkout() {
    let engine = crate::Lodestar::open_in_memory().unwrap();
    let goal = engine
        .define_goal(crate::GoalKind::Objective, "Ship", "ship the thing", None)
        .unwrap();
    let task = engine.create_task(&goal.id, "build it", "built").unwrap();

    let error = engine
        .merge_evidence(&task.id, "deadbeef", "agent-a")
        .expect_err("an unknown checkout must be reported, not guessed at");

    assert!(
        error.to_string().contains("which checkout it serves"),
        "{error}"
    );
}
